package com.ghatana.media.integration;

import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;
import java.util.Random;
import java.util.concurrent.TimeUnit;

/**
 * Real input for the J-08 video enhancement journey. The clean reference is generated by FFmpeg's {@code testsrc}
 * (moving pattern, colour bars and a frame/timecode text counter) at 640x360, 25 fps, with an AAC sine tone. The
 * degraded version is derived from the DECODED reference by (1) a Gaussian blur, (2) a very low quality re-encode
 * (blockiness), (3) additive Gaussian noise of a KNOWN sigma applied in Java to the decoded pixels with a fixed
 * seed, and (4) a high quality encode that keeps the noise. The audio of the reference is stream-copied.
 */
final class VideoEnhancementFixture {
    static final int WIDTH = 640;
    static final int HEIGHT = 360;
    static final int FPS = 25;

    private VideoEnhancementFixture() { }

    static byte[] reference(Path ffmpeg, Path work, int seconds) throws Exception {
        Path out = work.resolve("reference.mp4");
        run(List.of(ffmpeg.toString(), "-nostdin", "-v", "error", "-f", "lavfi", "-i",
                "testsrc=size=" + WIDTH + "x" + HEIGHT + ":rate=" + FPS + ":duration=" + seconds,
                "-f", "lavfi", "-i", "sine=frequency=440:sample_rate=48000:duration=" + seconds,
                "-c:v", "libx264", "-preset", "medium", "-crf", "12", "-pix_fmt", "yuv420p",
                "-c:a", "aac", "-b:a", "96k", "-shortest", "-y", out.toString()));
        return Files.readAllBytes(out);
    }

    /** Blur, low-bitrate blockiness, then Gaussian noise of {@code sigma} (luma 8-bit levels; chroma sigma/2). */
    static byte[] degraded(Path ffmpeg, Path work, byte[] reference, double sigma, long seed, int blockCrf)
            throws Exception {
        Path ref = work.resolve("degrade-source.mp4");
        Files.write(ref, reference);
        Path lowbit = work.resolve("lowbit.mp4");
        run(List.of(ffmpeg.toString(), "-nostdin", "-v", "error", "-i", ref.toString(), "-an", "-vf", "gblur=sigma=1.0",
                "-c:v", "libx264", "-preset", "veryfast", "-crf", Integer.toString(blockCrf), "-pix_fmt", "yuv420p",
                "-y", lowbit.toString()));
        Path out = work.resolve("degraded.mp4");
        List<String> decode = List.of(ffmpeg.toString(), "-nostdin", "-v", "error", "-i", lowbit.toString(), "-f",
                "rawvideo", "-pix_fmt", "yuv420p", "-");
        List<String> encode = List.of(ffmpeg.toString(), "-nostdin", "-v", "error", "-f", "rawvideo", "-pix_fmt",
                "yuv420p", "-s", WIDTH + "x" + HEIGHT, "-r", Integer.toString(FPS), "-i", "-", "-i", ref.toString(),
                "-map", "0:v", "-map", "1:a", "-c:v", "libx264", "-preset", "medium", "-crf", "16", "-pix_fmt",
                "yuv420p", "-c:a", "copy", "-shortest", "-y", out.toString());
        Process decoder = new ProcessBuilder(decode).redirectError(ProcessBuilder.Redirect.DISCARD).start();
        Process encoder = new ProcessBuilder(encode).redirectError(ProcessBuilder.Redirect.DISCARD)
                .redirectOutput(ProcessBuilder.Redirect.DISCARD).start();
        int lumaBytes = WIDTH * HEIGHT;
        int frameBytes = lumaBytes * 3 / 2;
        Random random = new Random(seed);
        byte[] frame = new byte[frameBytes];
        try (InputStream in = decoder.getInputStream(); OutputStream sink = encoder.getOutputStream()) {
            while (true) {
                int read = in.readNBytes(frame, 0, frameBytes);
                if (read == 0) break;
                if (read != frameBytes) throw new IllegalStateException("partial raw frame");
                for (int i = 0; i < frameBytes; i++) {
                    double s = i < lumaBytes ? sigma : sigma / 2;
                    int value = (frame[i] & 0xFF) + (int) Math.round(random.nextGaussian() * s);
                    frame[i] = (byte) Math.max(0, Math.min(255, value));
                }
                sink.write(frame);
            }
        }
        if (!decoder.waitFor(120, TimeUnit.SECONDS) || decoder.exitValue() != 0) {
            throw new IllegalStateException("degrade decoder failed");
        }
        if (!encoder.waitFor(300, TimeUnit.SECONDS) || encoder.exitValue() != 0) {
            throw new IllegalStateException("degrade encoder failed");
        }
        return Files.readAllBytes(out);
    }

    /** First lines of ffprobe frame PTS, time base and frame count of the first video stream. */
    record Probe(long timeBaseNum, long timeBaseDen, List<Long> pts, double durationSeconds, int audioStreams) { }

    static Probe probe(Path ffprobe, Path video) throws Exception {
        String frames = capture(List.of(ffprobe.toString(), "-v", "error", "-select_streams", "v:0", "-show_entries",
                "frame=pts:stream=time_base", "-of", "csv=p=0", video.toString()));
        long num = 0;
        long den = 0;
        List<Long> pts = new ArrayList<>();
        for (String line : frames.split("\\R")) {
            line = line.trim();
            while (line.endsWith(",")) line = line.substring(0, line.length() - 1);
            if (line.isEmpty()) continue;
            if (line.contains("/")) {
                String[] parts = line.split("/");
                num = Long.parseLong(parts[0]);
                den = Long.parseLong(parts[1]);
            } else {
                pts.add(Long.parseLong(line));
            }
        }
        java.util.Collections.sort(pts);
        double duration = Double.parseDouble(capture(List.of(ffprobe.toString(), "-v", "error", "-show_entries",
                "format=duration", "-of", "csv=p=0", video.toString())).trim());
        String audio = capture(List.of(ffprobe.toString(), "-v", "error", "-select_streams", "a", "-show_entries",
                "stream=index", "-of", "csv=p=0", video.toString()));
        int audioStreams = (int) audio.lines().filter(l -> !l.isBlank()).count();
        return new Probe(num, den, pts, duration, audioStreams);
    }

    /** MD5 of the audio packets (stream copy to the md5 muxer), independently of the product code. */
    static String audioMd5(Path ffmpeg, Path video) throws Exception {
        return capture(List.of(ffmpeg.toString(), "-nostdin", "-v", "error", "-i", video.toString(), "-map", "0:a",
                "-c", "copy", "-f", "md5", "-")).trim();
    }

    /** FFmpeg's own PSNR (all planes averaged) of two videos, as an independent cross-check of the Java metrics. */
    static double ffmpegPsnrY(Path ffmpeg, Path a, Path b) throws Exception {
        String log = capture(List.of(ffmpeg.toString(), "-nostdin", "-v", "info", "-i", a.toString(), "-i", b.toString(),
                "-lavfi", "[0:v]extractplanes=y[x];[1:v]extractplanes=y[y];[x][y]psnr", "-f", "null", "-"));
        for (String line : log.split("\\R")) {
            int at = line.indexOf("PSNR y:");
            int avg = at < 0 ? -1 : line.indexOf("average:", at);
            if (avg >= 0) return Double.parseDouble(line.substring(avg + "average:".length()).trim().split("\\s+")[0]);
        }
        throw new IllegalStateException("no psnr summary: " + log);
    }

    static double ffmpegSsimY(Path ffmpeg, Path a, Path b) throws Exception {
        String log = capture(List.of(ffmpeg.toString(), "-nostdin", "-v", "info", "-i", a.toString(), "-i", b.toString(),
                "-lavfi", "[0:v]extractplanes=y[x];[1:v]extractplanes=y[y];[x][y]ssim", "-f", "null", "-"));
        for (String line : log.split("\\R")) {
            int at = line.indexOf("SSIM Y:");
            if (at >= 0) return Double.parseDouble(line.substring(at + "SSIM Y:".length()).trim().split("\\s+")[0]);
            at = line.indexOf("SSIM All:");
            if (at >= 0) return Double.parseDouble(line.substring(at + "SSIM All:".length()).trim().split("\\s+")[0]);
        }
        throw new IllegalStateException("no ssim summary: " + log);
    }

    private static String capture(List<String> command) throws Exception {
        Process process = new ProcessBuilder(command).redirectErrorStream(true).start();
        String text = new String(process.getInputStream().readAllBytes());
        if (!process.waitFor(300, TimeUnit.SECONDS) || process.exitValue() != 0) {
            throw new IllegalStateException(command.get(0) + " failed: " + text);
        }
        return text;
    }

    private static void run(List<String> command) throws IOException, InterruptedException {
        Process process = new ProcessBuilder(command).redirectErrorStream(true).start();
        byte[] log = process.getInputStream().readAllBytes();
        if (!process.waitFor(300, TimeUnit.SECONDS) || process.exitValue() != 0) {
            throw new IllegalStateException("ffmpeg failed: " + new String(log));
        }
    }
}
